package pzvrphysicality;
import java.util.*;import org.joml.Matrix4f;import org.joml.Quaternionf;import org.joml.Vector3f;import zombie.core.skinnedmodel.model.*;import zombie.core.skinnedmodel.model.jassimp.*;
public final class NativeHeldPhoneContactTest {
 private static int checks;private static void check(boolean value,String why){if(!value)throw new AssertionError(why);checks++;}private static void rejects(Runnable action,String why){try{action.run();throw new AssertionError(why);}catch(IllegalArgumentException expected){checks++;}}
 private static final float[] V={0,0,0,1,0,0,0,1,0,0,0,1};private static final int[] F={0,1,2,0,3,1,0,2,3,1,3,2};
 private static ProcessedAiScene scene(float[] v,int[] f){var result=new ProcessedAiScene();result.add(new ImportedStaticMesh(v,f));return result;}
 private static void uploaded(ModelMesh mesh,ProcessedAiScene scene){mesh.vb=new VertexBufferObject();NativeHeldFbxCpu.uploadedForTest(mesh,scene.first().vertices(),scene.first().faces(),null);}
 private static void load(ModelMesh mesh,ProcessedAiScene scene){NativeHeldFbxCpu.beginForTest(mesh,scene);mesh.modificationCount++;NativeHeldFbxCpu.end(mesh,null);uploaded(mesh,scene);}
 private static void cpu(){Main.ready=true;NativeHeldFbxCpu.clearForTest();var mesh=new ModelMesh();var points=V.clone();var indices=F.clone();load(mesh,scene(points,indices));var data=NativeHeldFbxCpu.get(mesh);check(data!=null&&data.revision()==1,"successful original FBX loader revision accepted");check(Arrays.equals(data.vertices(),V)&&Arrays.equals(data.faces(),F),"exact upload positions/indices retained");points[0]=42;indices[0]=3;check(Arrays.equals(data.vertices(),V)&&Arrays.equals(data.faces(),F),"source loader arrays detached");var output=data.vertices();output[0]=17;check(data.vertices()[0]==0,"published CPU arrays immutable");mesh.vb=new VertexBufferObject();check(NativeHeldFbxCpu.get(mesh)==null,"same mesh with replaced native VBO invalidates payload");
  mesh=new ModelMesh();load(mesh,scene(V.clone(),F.clone()));mesh.ready=false;check(NativeHeldFbxCpu.get(mesh)==null,"cold original GPU/asset readiness fails closed");mesh.ready=true;mesh.skinningData=new SkinningData();check(NativeHeldFbxCpu.get(mesh)==null,"skinned geometry never promoted");mesh.skinningData=null;mesh.modificationCount++;check(NativeHeldFbxCpu.get(mesh)==null,"asset reload revision invalidates collider");
  mesh=new ModelMesh();NativeHeldFbxCpu.beginForTest(mesh,scene(V.clone(),F.clone()));mesh.modificationCount++;NativeHeldFbxCpu.end(mesh,new IllegalStateException());check(NativeHeldFbxCpu.get(mesh)==null,"failed original FBX loader cannot publish");mesh=new ModelMesh();NativeHeldFbxCpu.beginForTest(mesh,scene(V.clone(),F.clone()));NativeHeldFbxCpu.end(mesh,null);check(NativeHeldFbxCpu.get(mesh)==null,"unchanged native revision is not a receipt");
  mesh=new ModelMesh();var changing=scene(V.clone(),F.clone());NativeHeldFbxCpu.beginForTest(mesh,changing);changing.add(new ImportedStaticMesh(V,F));mesh.modificationCount++;NativeHeldFbxCpu.end(mesh,null);check(NativeHeldFbxCpu.get(mesh)==null,"changed original scene selection rejected");
  mesh=new ModelMesh();float[] mutable=V.clone();NativeHeldFbxCpu.beginForTest(mesh,scene(mutable,F.clone()));mutable[0]=.2f;mesh.modificationCount++;NativeHeldFbxCpu.end(mesh,null);check(NativeHeldFbxCpu.get(mesh)==null,"CPU mutation during original upload invalidates copy");
  mesh=new ModelMesh();load(mesh,scene(V.clone(),F.clone()));mesh.minXyz.x=.2f;check(NativeHeldFbxCpu.get(mesh)==null,"loaded native bounds must match copied payload");mesh=new ModelMesh();mesh.path=new zombie.asset.AssetPath("Other.fbx");load(mesh,scene(V.clone(),F.clone()));check(NativeHeldFbxCpu.get(mesh)==null,"only exact phone asset is retained");
  mesh=new ModelMesh();var outer=mesh;var outerScene=scene(V.clone(),F.clone());NativeHeldFbxCpu.beginForTest(outer,outerScene);NativeHeldFbxCpu.beginForTest(new ModelMesh(),new ProcessedAiScene());NativeHeldFbxCpu.end(new ModelMesh(),null);outer.modificationCount++;NativeHeldFbxCpu.end(outer,null);uploaded(outer,outerScene);check(NativeHeldFbxCpu.get(outer)!=null,"unsupported nested load restores outer native scope");
  mesh=new ModelMesh();var queued=scene(V.clone(),F.clone());NativeHeldFbxCpu.beginForTest(mesh,queued);mesh.modificationCount++;NativeHeldFbxCpu.end(mesh,null);check(NativeHeldFbxCpu.get(mesh)==null,"old ready VBO cannot stand in for queued new FBX upload");NativeHeldFbxCpu.uploadedForTest(mesh,new VertexBufferObject.VertexArray(V.clone()),F.clone(),null);check(NativeHeldFbxCpu.get(mesh)==null,"different upload array identities cannot match original payload");uploaded(mesh,queued);check(NativeHeldFbxCpu.get(mesh)!=null,"exact delayed native upload completes the CPU/render receipt");
  mesh=new ModelMesh();queued=scene(V.clone(),F.clone());NativeHeldFbxCpu.beginForTest(mesh,queued);uploaded(mesh,queued);check(NativeHeldFbxCpu.get(mesh)==null,"early upload still waits for successful native loader revision");mesh.modificationCount++;NativeHeldFbxCpu.end(mesh,null);check(NativeHeldFbxCpu.get(mesh)!=null,"upload-before-load-end is paired with correct successful native revision");
  mesh=new ModelMesh();queued=scene(V.clone(),F.clone());NativeHeldFbxCpu.beginForTest(mesh,queued);mesh.modificationCount++;NativeHeldFbxCpu.end(mesh,null);NativeHeldFbxCpu.uploadedForTest(mesh,queued.first().vertices(),queued.first().faces(),new IllegalStateException());check(NativeHeldFbxCpu.get(mesh)==null,"failed original upload never supplies a collider");
  Main.ready=false;mesh=new ModelMesh();load(mesh,scene(V.clone(),F.clone()));check(NativeHeldFbxCpu.get(mesh)!=null,"passive exact payload registration is independent of later world option enable");Main.ready=true;
  rejects(()->new NativeHeldFbxCpu.Data(new float[24003],F,1),"bounded CPU vertex budget");rejects(()->new NativeHeldFbxCpu.Data(V,new int[]{0,1,4},1),"invalid FBX triangle index");float[] bad=V.clone();bad[0]=Float.NaN;rejects(()->new NativeHeldFbxCpu.Data(bad,F,1),"nonfinite FBX positions");
 }
 private static float[] palette(int count){var values=new float[count*12];for(int n=0;n<count;n++){values[n*12]=values[n*12+5]=values[n*12+10]=1;values[n*12+3]=n*.1f;}return values;}
 private static void transaction(){
  float[] before={100,200,3,0,0,0,1},after={100.02f,200.03f,3.01f,0,0,0,1};var transform=NativeHeldTransaction.render(before,after,1,100,200,0);check(transform.getTranslation(new Vector3f()).equals(new Vector3f(-.02f,.01f,-.03f),.00002f),"world contact translation maps exactly to native render coordinates");
  var actor=new Matrix4f().translation(2,3,4).scale(-.015f,.015f,.015f).rotateY(.4f).get(new float[16]);var rows=new float[2*68];new Matrix4f().translation(2,3,4).get(rows,68);new Matrix4f().translation(2,3,4).get(rows,104);rows[92]=2;rows[93]=3;rows[94]=4;rows[95]=.4f;var poses=palette(8);var savedRows=rows.clone();var savedPoses=poses.clone();boolean[] bones=HeldContactPalette.subtree(List.of(-1,0,1,2,0,4,0,6),1,6);var plan=new HeldContactPalette.Plan();NativeHeldTransaction.palette(plan,poses,0,bones,actor,transform);NativeHeldTransaction.item(plan,rows,1,transform);check(plan.commit(()->true),"phone plus wrist/socket transaction commits atomically");check(Arrays.equals(Arrays.copyOf(rows,68),Arrays.copyOf(savedRows,68)),"native existing held/body row unchanged");for(int bone:new int[]{0,4,5})check(Arrays.equals(Arrays.copyOfRange(poses,bone*12,bone*12+12),Arrays.copyOfRange(savedPoses,bone*12,bone*12+12)),"torso/opposite wrist native palette preserved "+bone);check(Math.abs(rows[80]-savedRows[80]+.02f)<.00002f&&Math.abs(rows[81]-savedRows[81]-.01f)<.00002f,"final same-frame phone follows actual contact response");check(Arrays.equals(Arrays.copyOfRange(rows,68,84),Arrays.copyOfRange(rows,104,120)),"native newly appended current/history draw matrices stay coherent");check(rows[95]==.4f,"native phone bounds size untouched");
  var rotated=after.clone();var q=new Quaternionf().rotationZ((float)Math.toRadians(10));rotated[3]=q.x;rotated[4]=q.y;rotated[5]=q.z;rotated[6]=q.w;transform=NativeHeldTransaction.render(before,rotated,1,100,200,0);var renderBefore=new Vector3f(0,3,0);var renderAfter=transform.transformPosition(new Vector3f(renderBefore));check(renderAfter.equals(new Vector3f(-.02f,3.01f,-.03f),.00002f),"angular correction pivots at exact tracked target rather than scene origin");check(Math.abs(transform.determinant()-1)<.001,"world/render reflection conversion preserves rigid rotation");
  float[] shared=palette(8),original=shared.clone();plan=new HeldContactPalette.Plan();NativeHeldTransaction.palette(plan,shared,0,bones,actor,transform);int[] calls={0};check(!plan.commit(()->++calls[0]==1)&&Arrays.equals(shared,original),"late mode/ownership rejection restores every rotated wrist/socket value");plan=new HeldContactPalette.Plan();NativeHeldTransaction.palette(plan,shared,0,bones,actor,transform);shared[12]=2;check(!plan.commit(()->true)&&shared[12]==2,"changed native palette wins over pending phone correction");
  var far=after.clone();far[0]+=.1f;rejects(()->NativeHeldTransaction.render(before,far,1,100,200,0),"unsafe deep contact correction rejected");var angle=after.clone();q.rotationZ((float)Math.toRadians(16));angle[3]=q.x;angle[4]=q.y;angle[5]=q.z;angle[6]=q.w;rejects(()->NativeHeldTransaction.render(before,angle,1,100,200,0),"unsupported angular correction rejected");
 }
 public static void main(String[] args){cpu();transaction();System.out.println("Native phone contact payload: "+checks+" checks passed; authored FBX/atomic frame records only");}
}
